async function* splitLines(chunks, maxBuffer = 1024) {
  const NEWLINE = "\n".charCodeAt(0);
  const line = Buffer.alloc(maxBuffer);
  let end = 0;
  for await (const chunk of chunks) {
    for (const byte of chunk) {
